/**
 * SentinelAI Anti-Hallucination Evidence Verifier
 * Enforces the core invariant: "AI proposes, code verifies."
 *
 * Every AI finding MUST link to an evidence ID produced by deterministic detectors.
 * Any AI claim that lacks valid evidence or references a non-existent ID
 * is strictly DROPPED and logged in the agent trace.
 */

/**
 * Verifies AI findings against deterministic ground-truth evidence.
 * @param {Array<any>} aiFindings - Findings returned from Gemini / LLM
 * @param {Array<any>} deterministicEvidence - Evidence generated by deterministic code detectors
 * @returns {{
 *   verifiedFindings: Array<any>,
 *   unsupportedCount: number,
 *   droppedClaims: Array<any>,
 *   verifierSummary: string,
 *   traceNote: string
 * }}
 */
export function verifyAiClaims(aiFindings = [], deterministicEvidence = []) {
  if (!Array.isArray(aiFindings)) {
    return {
      verifiedFindings: [],
      unsupportedCount: 0,
      droppedClaims: [],
      verifierSummary: 'No AI findings to verify',
      traceNote: '0 findings presented by AI',
    };
  }

  // Index deterministic evidence by its unique ID
  const evidenceMap = new Map();
  for (const item of deterministicEvidence) {
    if (item && item.id) {
      evidenceMap.set(item.id, item);
    }
  }

  const verifiedFindings = [];
  const droppedClaims = [];

  for (const finding of aiFindings) {
    const evidenceId = finding?.evidenceId;

    if (evidenceId && evidenceMap.has(evidenceId)) {
      const groundTruth = evidenceMap.get(evidenceId);
      // Merge deterministic ground-truth with AI reasoning
      verifiedFindings.push({
        ...finding,
        groundTruthVerified: true,
        evidenceType: groundTruth.type,
        subtype: groundTruth.subtype,
        severity: finding.severity || groundTruth.severity,
        span: groundTruth.span,
        lineNumber: groundTruth.lineNumber,
        snippet: groundTruth.snippet,
        text: groundTruth.text,
        ruleDetails: groundTruth.details,
      });
    } else {
      // Hallucinated or unsupported claim: discard it!
      droppedClaims.push({
        unsupportedFinding: finding,
        reason: evidenceId
          ? `Referenced unknown or unproven evidence ID "${evidenceId}"`
          : 'Missing mandatory evidence ID linkage',
      });
    }
  }

  // Include any deterministic evidence items that AI failed to mention,
  // ensuring no high-risk detector alerts are quietly dropped by LLM
  const coveredIds = new Set(verifiedFindings.map((f) => f.evidenceId));
  for (const [id, evidence] of evidenceMap.entries()) {
    if (!coveredIds.has(id)) {
      verifiedFindings.push({
        evidenceId: id,
        explanation:
          evidence.details ||
          `Deterministic ${evidence.type} alert (${evidence.subtype || 'general'})`,
        severity: evidence.severity,
        groundTruthVerified: true,
        isDeterministicFallback: true,
        evidenceType: evidence.type,
        subtype: evidence.subtype,
        span: evidence.span,
        lineNumber: evidence.lineNumber,
        snippet: evidence.snippet,
        text: evidence.text,
        suggestedFix: evidence.fixSuggestion || null,
      });
    }
  }

  const unsupportedCount = droppedClaims.length;
  const traceNote =
    unsupportedCount > 0
      ? `${unsupportedCount} unsupported AI claims removed (anti-hallucination shield)`
      : `All ${verifiedFindings.length} findings verified against deterministic evidence`;

  return {
    verifiedFindings,
    unsupportedCount,
    droppedClaims,
    verifierSummary: traceNote,
    traceNote,
  };
}
